namespace Vnecoms\VendorsCategory\Model\Rewrite;

use Vnecoms\VendorsCategory\Model\Category;
use Magento\UrlRewrite\Model\OptionProvider;
use Magento\UrlRewrite\Model\UrlFinderInterface;
use Magento\UrlRewrite\Service\V1\Data\UrlRewrite;
use Magento\UrlRewrite\Service\V1\Data\UrlRewriteFactory;

class CurrentUrlRewritesRegenerator
{
    /** @var \Vnecoms\VendorsCategory\Model\Rewrite\CategoryUrlPathGenerator */
    protected $categoryUrlPathGenerator;

    /** @var \Magento\UrlRewrite\Service\V1\Data\UrlRewriteFactory */
    protected $urlRewriteFactory;

    /** @var UrlFinderInterface */
    protected $urlFinder;

    /** @var \Vnecoms\VendorsCategory\Model\Category */
    protected $category;

    /**
     * @param \Vnecoms\VendorsCategory\Model\Rewrite\CategoryUrlPathGenerator $categoryUrlPathGenerator
     * @param \Magento\UrlRewrite\Service\V1\Data\UrlRewriteFactory           $urlRewriteFactory
     * @param UrlFinderInterface                                              $urlFinder
     */
    public function __construct(
        CategoryUrlPathGenerator $categoryUrlPathGenerator,
        UrlRewriteFactory $urlRewriteFactory,
        UrlFinderInterface $urlFinder
    ) {
        $this->categoryUrlPathGenerator = $categoryUrlPathGenerator;
        $this->urlRewriteFactory = $urlRewriteFactory;
        $this->urlFinder = $urlFinder;
    }

    /**
     * Generate list based on current url rewrites.
     *
     * @param int                                     $storeId
     * @param \Vnecoms\VendorsCategory\Model\Category $category
     *
     * @return \Magento\UrlRewrite\Service\V1\Data\UrlRewrite[]
     */
    public function generate($storeId, Category $category, $isIndexMode)
    {
        $this->category = $category;

        $currentUrlRewrites = $this->urlFinder->findAllByData(
            [
                UrlRewrite::STORE_ID => $storeId,
                UrlRewrite::ENTITY_ID => $category->getId(),
                UrlRewrite::ENTITY_TYPE => 'vendor_category',
            ]
        );

        $urlRewrites = [];
        foreach ($currentUrlRewrites as $rewrite) {
            if ($rewrite->getIsAutogenerated()) {
                $urlRewrites = array_merge($urlRewrites, $this->generateForAutogenerated($rewrite, $storeId, $isIndexMode));
            } else {
                $urlRewrites = array_merge($urlRewrites, $this->generateForCustom($rewrite, $storeId, $isIndexMode));
            }
        }

        return $urlRewrites;
    }

    /**
     * @param \Magento\UrlRewrite\Service\V1\Data\UrlRewrite $url
     * @param int                                            $storeId
     *
     * @return array
     */
    protected function generateForAutogenerated($url, $storeId, $isIndexMode)
    {
        $urls = [];
        if ($this->category->getData('save_rewrites_history')) {
            $targetPath = $this->categoryUrlPathGenerator->getUrlPathWithSuffix($this->category, $storeId, $isIndexMode);
            if ($url->getRequestPath() !== $targetPath) {
                $urls[$url->getRequestPath().'_'.$storeId] = $this->urlRewriteFactory->create()
                    ->setEntityType('vendor_category')
                    ->setEntityId($this->category->getId())
                    ->setRequestPath($url->getRequestPath())
                    ->setTargetPath($targetPath)
                    ->setRedirectType(OptionProvider::PERMANENT)
                    ->setStoreId($storeId)
                    ->setIsAutogenerated(0);
            }
        }

        return $urls;
    }

    /**
     * @param \Magento\UrlRewrite\Service\V1\Data\UrlRewrite $url
     * @param int                                            $storeId
     *
     * @return array
     */
    protected function generateForCustom($url, $storeId, $isIndexMode)
    {
        $urls = [];
        $targetPath = !$url->getRedirectType()
            ? $url->getTargetPath()
            : $this->categoryUrlPathGenerator->getUrlPathWithSuffix($this->category, $storeId, $isIndexMode);
        if ($url->getRequestPath() !== $targetPath) {
            $urls[$url->getRequestPath().'_'.$storeId] = $this->urlRewriteFactory->create()
                ->setEntityType('vendor_category')
                ->setEntityId($this->category->getId())
                ->setRequestPath($url->getRequestPath())
                ->setTargetPath($targetPath)
                ->setRedirectType($url->getRedirectType())
                ->setStoreId($storeId)
                ->setDescription($url->getDescription())
                ->setIsAutogenerated(0)
                ->setMetadata($url->getMetadata());
        }

        return $urls;
    }
}
